cases.extend([
('src/core/issueGraphDecision.vibe', 'issue-ancestor-base', 'issueAncestorAt', 'if (steps <= 0) return start', 'if (steps <= 0) return 0', 'zero links retains the initial parent'),
('src/core/issueGraphDecision.vibe', 'issue-ancestor-root', 'issueAncestorAt', 'if (previous === 0) return 0', 'if (previous === 0) return 1', 'a reached root absorbs subsequent links'),
('src/core/issueGraphDecision.vibe', 'issue-ancestor-missing', 'issueAncestorAt', 'if (found === undefined) return -1', 'if (found === undefined) return 0', 'missing ancestors are not roots'),
('src/core/issueGraphDecision.vibe', 'issue-ancestor-parent', 'issueAncestorAt', 'return found.parent', 'return found.number', 'each link advances to its first matching record parent'),
('src/core/issueGraphDecision.vibe', 'issue-ancestor-first', 'issueAncestorAt', 'items.find((item) => item.number === previous)', 'items.find((item) => item.number !== previous)', 'the first matching identity supplies the parent'),
('src/core/issueGraphDecision.vibe', 'issue-ancestor-predecessor', 'issueAncestorAt', 'steps - 1)', 'steps - 2)', 'the measure advances one link and satisfies recursive domain'),
('src/core/issueGraphDecision.vibe', 'issue-link-positive-child', 'canLinkIssues', ' || child <= 0', '', 'accepted links have a positive child'),
('src/core/issueGraphDecision.vibe', 'issue-link-positive-parent', 'canLinkIssues', 'parent <= 0 || ', '', 'accepted links have a positive parent'),
('src/core/issueGraphDecision.vibe', 'issue-link-self', 'canLinkIssues', 'if (parent <= 0 || child <= 0 || child === parent || !items.some((i) => i.number === child)) return false', 'if (child === parent) return true\n  if (parent <= 0 || child <= 0 || child === parent || !items.some((i) => i.number === child)) return false', 'self links are refused'),
('src/core/issueGraphDecision.vibe', 'issue-link-child-exists', 'canLinkIssues', ' || !items.some((i) => i.number === child)', '', 'the child must exist'),
('src/core/issueGraphDecision.vibe', 'issue-link-ancestor-child', 'canLinkIssues', 'if (next === child) return false', 'if (false) return false', 'the traversed ancestor prefix never contains the child'),
('src/core/issueGraphDecision.vibe', 'issue-link-missing-parent', 'canLinkIssues', 'if (found === undefined) return false', 'if (found === undefined) return true', 'a missing ancestor is never accepted'),
('src/core/issueGraphDecision.vibe', 'issue-link-step', 'canLinkIssues', 'next = found.parent', 'next = 0', 'a claimed root follows the actual first-matching parent'),
('src/core/issueGraphDecision.vibe', 'issue-link-cycle-bound', 'canLinkIssues', 'steps <= items.length)', 'steps <= items.length + 1)', 'cyclic traversal terminates within the proved bound'),
('src/core/issueGraphDecision.vibe', 'issue-link-root', 'canLinkIssues', 'return next === 0', 'return true', 'an exhausted non-root path is refused'),
('src/core/issueGraphDecision.vibe', 'graph-creates-split', 'issueCreates', ' || op === "split"', '', 'a split creates an issue'),
('src/core/issueGraphDecision.vibe', 'graph-next-above', 'nextIssueNumber', 'return top + 1', 'return top', 'a created issue takes a number above every issue'),
('src/core/issueGraphDecision.vibe', 'graph-next-positive', 'nextIssueNumber', 'let top = 0', 'let top = -1', 'a created issue takes a positive number'),
('src/core/issueGraphDecision.vibe', 'graph-next-scan', 'nextIssueNumber', 'if (items[i]!.number > top) top = items[i]!.number', 'if (items[i]!.number > top + 1) top = items[i]!.number', 'the scan sees every number'),
('src/core/issueGraphDecision.vibe', 'graph-edit-link-parent', 'editedIssue', 'parent: edit.parent, notes', 'parent: issue.parent, notes', 'a link sets the parent it names'),
('src/core/issueGraphDecision.vibe', 'graph-edit-comment-parent', 'editedIssue', 'comments: issue.comments + 1,', 'parent: 0, comments: issue.comments + 1,', 'only a link changes a parent'),
('src/core/issueGraphDecision.vibe', 'graph-edit-number', 'editedIssue', 'return { ...declineVip(issue), notes', 'return { ...declineVip(issue), number: 0, notes', 'an edit keeps the issue number'),
('src/core/issueGraphDecision.vibe', 'graph-split-parent', 'issuesAfter', 'parent: edit.op === "split" ? edit.number : 0', 'parent: edit.op === "split" ? edit.parent : 0', 'a split goes under the issue it splits'),
('src/core/issueGraphDecision.vibe', 'graph-split-self', 'issuesAfter', 'parent: edit.op === "split" ? edit.number : 0', 'parent: edit.op === "split" ? created.number : 0', 'a split never makes the new issue its own ancestor'),
('src/core/issueGraphDecision.vibe', 'graph-create-self', 'issuesAfter', 'parent: edit.op === "split" ? edit.number : 0', 'parent: edit.op === "split" ? edit.number : created.number', 'a created issue never is its own ancestor'),
('src/core/issueGraphDecision.vibe', 'graph-created-last', 'issuesAfter', 'return [{ ...created, parent: edit.op === "split" ? edit.number : 0 }, ...items]', 'return [...items, { ...created, parent: edit.op === "split" ? edit.number : 0 }]', 'a created issue goes first'),
('src/core/issueGraphDecision.vibe', 'graph-edit-others', 'issuesAfter', 'issue.number === edit.number ? editedIssue(issue, edit) : issue', 'issue.number !== edit.number ? editedIssue(issue, edit) : issue', 'an edit changes only its issue'),
('src/history/replayDecision.vibe', 'history-replay-order', 'replayHistory', 'history = replayEvent(history, events[i]!)', 'history = replayEvent(history, events[events.length - 1 - i]!)', 'replay applies the journal in order'),
('src/history/replayDecision.vibe', 'history-step-applies', 'replayStep', '? replayEvent(history, event) : history', '? history : history', 'the replay step is replayEvent inside its domain'),
('src/history/replayDecision.vibe', 'history-record-applies', 'recordedHistory', 'return { decision, history: replayEvent(history, decision.event) }', 'return { decision, history }', 'an accepted event moves the live history'),
('src/history/replayDecision.vibe', 'history-record-decides', 'recordedHistory', 'const decision = decideWithinCapacity(history, intent)', 'const decision = decideWithinCapacity({ ...history, epics: [] }, intent)', 'the live history records the sequencer decision'),
('src/core/replayDecision.vibe', 'replay-order', 'replayLog', 'current = apply(current, events[i]!)', 'current = apply(current, events[events.length - 1 - i]!)', 'replay applies the log in order'),
('src/core/replayDecision.vibe', 'conversation-step-applies', 'conversationStep', '? apply(conversation, event) : conversation', '? conversation : conversation', 'the replay step is apply below capacity'),
('src/core/replayDecision.vibe', 'record-applies', 'recordedConversation', 'conversation: apply(conversation, decision.event), log', 'conversation, log', 'an accepted event moves the live conversation'),
('src/core/replayDecision.vibe', 'record-journal-order', 'recordedConversation', 'log: [...log, decision.event]', 'log: [decision.event, ...log]', 'an accepted event goes at the end of the log'),
('src/core/replayDecision.vibe', 'record-refusal-keeps-log', 'recordedConversation', 'if (!decision.ok) return { decision, conversation, log }', 'if (!decision.ok) return { decision, conversation, log: [] }', 'a refused intent keeps the log'),
])


