('sandbox-host-cause-separator', 'receiptCause', 'refusal + ":" + reason', 'refusal + reason', 'a recorded cause follows its refusal after a colon'),
('sandbox-host-cause-dropped', 'receiptCause', 'return hasReason ? refusal + ":" + reason : refusal', 'return refusal', 'a recorded cause is kept'),
('sandbox-host-unavailable-only', 'causeOf', 'if (hasTag && tag === "Unavailable" && hasReason) return reason', 'if (hasTag && hasReason) return reason', 'only an Unavailable answers its own reason'),
('sandbox-host-untagged', 'causeOf', 'return hasTag ? tag : "defect"', 'return tag', 'an untagged failure is a defect'),
('sandbox-host-step-refused', 'stepOutcome', 'return reason === "" ? "done" : "refused"', 'return "done"', 'a refusal reason marks the step refused'),
('sandbox-host-stored-number', 'storedNumber', 'return isNumber ? value : 0', 'return value', 'a value of another type is no generation'),
('sandbox-host-stored-text', 'storedText', 'return isText ? value : ""', 'return value', 'a value of another type is no transcript'),
('sandbox-host-alarm-retry', 'alarmKind', 'if (pending) return "retry"', 'if (pending && running <= 0) return "retry"', 'a pending operation retries even while sandboxes run'),
('sandbox-host-alarm-meter', 'alarmKind', 'return running > 0 ? "meter" : "clear"', 'return running >= 0 ? "meter" : "clear"', 'nothing running clears the alarm'),
('sandbox-host-room-top', 'safeRoom', '0 <= n && n < 9007199254740991', '0 <= n && n <= 9007199254740991', 'the last safe integer has no room for another step'),
('sandbox-host-room-negative', 'safeRoom', '0 <= n && n < 9007199254740991', 'n < 9007199254740991', 'a negative counter has no room'),
('sandbox-host-intent', 'intentType', 'return kind === "start" ? "start" : "stop"', 'return kind !== "stop" ? "start" : "stop"', 'only a start records a start'),
('sandbox-host-foreign', 'foreignLedger', 'return ledgerOwner !== owner', 'return false', "another owner's ledger is refused"),
('sandbox-host-complete-cancel', 'completionStep', 'return kind === "cancel-start" ? "cancel-start" : "stop"', 'return "stop"', 'a cancelled start completes as a cancellation'),
('sandbox-host-cancel-refusal', 'completionRefusal', 'return kind === "cancel-start" ? "start-failed" : ""', 'return ""', 'a cancelled start is recorded as failed'),
('sandbox-host-receipt-kind', 'receiptKind', 'return kind === "cancel-start" ? "start" : kind', 'return kind', 'a cancelled start answers the start asked for'),
('sandbox-host-out-of-minutes', 'outOfMinutes', 'return remaining === 0', 'return remaining <= 1', 'one remaining millisecond still starts'),
('sandbox-host-stop-role', 'mustStopAll', 'return remaining === 0 || !mayStart', 'return remaining === 0', 'a role that may not start stops every sandbox'),
('sandbox-host-stop-minutes', 'mustStopAll', 'return remaining === 0 || !mayStart', 'return !mayStart', 'exhausted minutes stop every sandbox'),
('sandbox-host-lease-ceiling', 'leaseShare', 'return Math.ceil(remaining / running)', 'return Math.floor(remaining / running)', 'a lease share rounds up'),
('sandbox-host-recovery-role', 'recoveryOf', 'if (kind === "start" && !mayStart) return "drop-start"', 'if (kind === "start") return "drop-start"', 'a permitted start completes'),
('sandbox-host-recovery-command', 'recoveryOf', 'if (kind === "command") return "await-command"', 'if (kind === "cancel-start") return "await-command"', 'a pending command is left to its fiber; the store settles one no fiber runs'),
('sandbox-host-unit-dot', 'conversationUnit', ' || unit === 46 || unit === 95', ' || unit === 95', 'a dot is a conversation unit'),
('sandbox-host-unit-slash', 'operationUnit', 'return conversationUnit(unit) || unit === 47', 'return conversationUnit(unit)', 'a slash is an operation unit'),
('sandbox-host-operation-empty', 'operationKey', 'if (id.length < 1 || id.length > 160) return false', 'if (id.length > 160) return false', 'an empty operation id is refused'),
('sandbox-host-operation-units', 'operationKey', 'if (!operationUnit(id.charCodeAt(i))) return false', 'if (!conversationUnit(id.charCodeAt(i))) return false', 'operation ids admit a slash'),
('sandbox-host-conversation-length', 'sandboxConversation', 'if (id.length < 1 || id.length > 120) return false', 'if (id.length < 1 || id.length > 121) return false', 'a conversation id has at most 120 units'),
('sandbox-host-ownerless', 'forbiddenCaller', 'return owner === "" || !mayStart', 'return !mayStart', 'a caller without an owner is refused'),
('sandbox-host-replay-generation', 'replayConflict', '(kind !== "start" && oldGeneration !== generation)', '(oldGeneration !== generation)', "a start's replay ignores the requested generation"),
('sandbox-host-replay-command', 'replayConflict', ' || oldCommand !== command', '', 'a different command conflicts'),
('sandbox-host-replay-order', 'replayAnswer', 'if (conflict) return "operation-conflict"', 'if (conflict && !refused) return "operation-conflict"', 'a conflict is refused before a refused receipt'),
('sandbox-host-admit-stale', 'freshAdmission', 'if (kind !== "start" && !generationMatches) return "stale-generation"', 'if (!generationMatches) return "stale-generation"', 'a start is never stale'),
('sandbox-host-admit-running', 'freshAdmission', 'if (kind === "start" && running) return "running"', 'if (kind === "start" && running) return "pending"', 'a start of a running sandbox answers it as it is'),
