('src/core/liveAnswerDecision.vibe', 'live-success-bottom', 'successStatus', '200 <= status', '100 <= status', 'a 1xx answer is not a success'),
('src/core/liveAnswerDecision.vibe', 'live-exact-ok', 'exactOk', 'return status === 200', 'return status === 200 || status === 204', 'a body-less 204 is not an answer'),
('src/core/liveAnswerDecision.vibe', 'live-account-read-denied', 'accountRead', 'if (status === 403) return "denied"', 'if (status === 401) return "denied"', 'a 403 read is a refusal'),
('src/core/liveAnswerDecision.vibe', 'live-account-read-ok', 'accountRead', 'return status === 200 ? "ok" : "unavailable"', 'return status === 200 || status === 204 ? "ok" : "unavailable"', 'a read needs a 200 answer'),
